  const ctx = (event && event.context) || {};
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  const channel = String(event.channel ?? ctx.channel ?? '');
  const accountId = String(event.accountId ?? ctx.accountId ?? '');
  if (sessionKey.includes('bni_tainan') && sessionKey.includes('line')) return true;
  if (channel === 'line' && accountId === 'bni_tainan') return true;
  return false;
}

function wasSendFailure(event) {
  const ctx = (event && event.context) || {};
  const success = event.success ?? ctx.success;
  const error = event.error ?? ctx.error;
  if (success === false) return true;
  if (success === undefined && error) return true;
  return false;
}

function extractTarget(event) {
  const ctx = (event && event.context) || {};
  let to = event.to ?? ctx.to ?? ctx.chatId;
  if (to) return String(to);
  // fallback: derive LINE user id from sessionKey tail (agent:bni_tainan:line:direct:u...)
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  const parts = sessionKey.split(':');
  const tail = parts[parts.length - 1];
  if (tail && tail.length > 10) return tail;
  return '';
}

function extractContent(event) {
  const ctx = (event && event.context) || {};
  return String(event.content ?? ctx.content ?? ctx.textContent ?? '').trim();
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'sent') return;

  probeDump(event);

  if (!isBniTainanLine(event)) return;
  if (!wasSendFailure(event)) return;

  const target = extractTarget(event);
  const content = extractContent(event);
  if (!target || !content) {
    logAction({ outcome: 'skip_missing_fields', target, hasContent: !!content });
    return;
  }

  const dedupeKey = target + '|' + content.slice(0, 100);
  const now = Date.now();
  const last = recentlyPushed.get(dedupeKey);
  if (last && (now - last) < DEDUPE_WINDOW_MS) {

