// 攔截真實 Telegram 發送 + 真實 spawn('openclaw', ...)，避免測試真的打通知或真的觸發 agent 續跑。
// 跑完還原真實 counter 檔案，不影響正式狀態。

const fs = require('fs');
const path = require('path');
const https = require('https');
const cp = require('child_process');

let telegramSentCount = 0;
https.request = function (opts, cb) {
  telegramSentCount++;
  const fakeRes = { on: () => {} };
  if (cb) setTimeout(() => cb(fakeRes), 0);
  return { on: () => {}, write: () => {}, end: () => {}, destroy: () => {} };
};

const spawnCalls = [];
cp.spawn = function (cmd, args, opts) {
  spawnCalls.push({ cmd, args, opts });
  return { unref: () => {} };
};

const HANDLER_PATH = path.join(process.env.HOME, '.openclaw', 'hooks', 'minimax-overload-autocontinue', 'handler.js');
const COUNTER_PATH = path.join(process.env.HOME, '.openclaw', 'workspace', 'state', 'minimax_overload_retry.json');

function mkEvent({ sessionKey = 'agent:main:telegram:direct:6124913915', text = '正常回覆' } = {}) {
  return { type: 'message', action: 'sent', sessionKey, context: { textContent: text } };
}

function resetCounter() {
  try { fs.unlinkSync(COUNTER_PATH); } catch (e) {}
}

function readCounters() {
  try { return JSON.parse(fs.readFileSync(COUNTER_PATH, 'utf-8')); } catch (e) { return {}; }
}

async function run() {
  let backup = null;
  try { backup = fs.readFileSync(COUNTER_PATH, 'utf-8'); } catch (e) {}

  delete require.cache[require.resolve(HANDLER_PATH)];
  const handler = require(HANDLER_PATH);
  let pass = 0, fail = 0;

  function check(name, cond) {
    console.log((cond ? '✅' : '❌'), name);
    cond ? pass++ : fail++;
  }

  const OVERLOAD_TEXT = 'The AI service is temporarily overloaded. Please try again in a moment.';

  console.log('=== 正常訊息不觸發，不寫入counter ===');
  resetCounter();
  spawnCalls.length = 0; telegramSentCount = 0;
  await handler(mkEvent({ text: '任務已完成，這是結果。' }));
  check('正常訊息不觸發spawn', spawnCalls.length === 0);
  check('正常訊息不觸發Telegram', telegramSentCount === 0);
  check('正常訊息不寫入counter檔', Object.keys(readCounters()).length === 0);

  console.log('=== 非message:sent事件應忽略 ===');
  spawnCalls.length = 0;
  await handler({ type: 'message', action: 'preprocessed', context: {} });
  await handler(null);
  check('非sent事件+null事件都不炸掉、不觸發', spawnCalls.length === 0);

  console.log('=== 第1次過載：自動觸發續跑+通知 ===');
  resetCounter();
  spawnCalls.length = 0; telegramSentCount = 0;
  await handler(mkEvent({ text: OVERLOAD_TEXT }));
  check('第1次觸發spawn一次', spawnCalls.length === 1);
  check('spawn呼叫openclaw agent --session-key帶正確session', spawnCalls[0].cmd === 'openclaw' && spawnCalls[0].args.includes('agent') && spawnCalls[0].args.includes('agent:main:telegram:direct:6124913915'));
  check('spawn呼叫帶--deliver', spawnCalls[0].args.includes('--deliver'));
  check('spawn呼叫帶「請繼續」', spawnCalls[0].args.includes('請繼續'));
  check('第1次發一則Telegram通知', telegramSentCount === 1);
  const c1 = readCounters()['agent:main:telegram:direct:6124913915'];
  check('counter記錄count=1', c1 && c1.count === 1 && c1.escalated === false);

  console.log('=== 第2、3次過載：持續自動續跑 ===');
  await handler(mkEvent({ text: OVERLOAD_TEXT }));
  await handler(mkEvent({ text: OVERLOAD_TEXT }));
  check('累計spawn共3次', spawnCalls.length === 3);
  check('累計Telegram共3則', telegramSentCount === 3);
  const c3 = readCounters()['agent:main:telegram:direct:6124913915'];
  check('counter記錄count=3', c3 && c3.count === 3 && c3.escalated === false);

  console.log('=== 第4次過載：不再自動續跑，改升級通知教練 ===');
  await handler(mkEvent({ text: OVERLOAD_TEXT }));
  check('第4次不再新增spawn(仍是3次)', spawnCalls.length === 3);
  check('第4次多發一則升級Telegram(共4則)', telegramSentCount === 4);
  const c4 = readCounters()['agent:main:telegram:direct:6124913915'];
  check('counter標記escalated=true', c4 && c4.escalated === true);

  console.log('=== escalated後再過載：靜默不再打擾 ===');
  await handler(mkEvent({ text: OVERLOAD_TEXT }));
  check('escalated後不再spawn', spawnCalls.length === 3);
  check('escalated後不再發Telegram(仍是4則)', telegramSentCount === 4);

  console.log('=== 恢復正常回覆後：counter重置，下次可重新從第1次算 ===');
  await handler(mkEvent({ text: '好的，任務完成了。' }));
  check('正常回覆後counter被清除', Object.keys(readCounters()).length === 0);

  spawnCalls.length = 0; telegramSentCount = 0;
  await handler(mkEvent({ text: OVERLOAD_TEXT }));
  const c5 = readCounters()['agent:main:telegram:direct:6124913915'];
  check('重置後再次過載重新從count=1開始', c5 && c5.count === 1 && c5.escalated === false);
  check('重置後重新觸發spawn', spawnCalls.length === 1);

  console.log('=== 不同session各自獨立計數 ===');
  resetCounter();
  spawnCalls.length = 0; telegramSentCount = 0;
  await handler(mkEvent({ sessionKey: 'agent:main:telegram:direct:AAA', text: OVERLOAD_TEXT }));
  await handler(mkEvent({ sessionKey: 'agent:kong:telegram:direct:BBB', text: OVERLOAD_TEXT }));
  const counters = readCounters();
  check('兩個session互不影響，各自count=1', counters['agent:main:telegram:direct:AAA']?.count === 1 && counters['agent:kong:telegram:direct:BBB']?.count === 1);

  console.log(`\n結果：${pass} 通過, ${fail} 失敗`);

  resetCounter();
  if (backup !== null) fs.writeFileSync(COUNTER_PATH, backup);

  process.exit(fail > 0 ? 1 : 0);
}

run();

