"use strict";

// OpenClaw Hook：minimax-overload-autocontinue
// 用途：MiniMax API 過載訊息被系統當成正常回覆送出時，事件驅動自動補一句「請繼續」，
//       最多3次，第4次改發Telegram請教練裁示。不做任何輪詢/定時檢查。
// 事件：message:sent（照 bot-relay / line-delivery-fallback handler 模板）
// 軍師建立 2026-09-06（教練凌晨交辦，拒絕輪詢方案後定案）

const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

const HOME = process.env.HOME;
const WORKSPACE = path.join(HOME, '.openclaw', 'workspace');
const COUNTER_PATH = path.join(WORKSPACE, 'state', 'minimax_overload_retry.json');
const OPENCLAW_CONFIG_PATH = path.join(HOME, '.openclaw', 'openclaw.json');
const PROBE_LOG = path.join(HOME, '.openclaw', 'logs', 'minimax-overload-autocontinue-probe.log');
const ACTION_LOG = path.join(HOME, '.openclaw', 'logs', 'minimax-overload-autocontinue-action.log');
const COACH_TELEGRAM_CHAT_ID = '6124913915';

const MAX_AUTO_RETRY = 3;

// MiniMax 已知過載訊息樣式（2026-09-06 教練實戰遇到的原句 + 常見變體）
const OVERLOAD_PATTERNS = [
  /AI service is temporarily overloaded/i,
  /service is currently overloaded/i,
  /temporarily overloaded.{0,40}try again/i,
];

function ensureDir(p) {
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

function probeDump(event) {
  try {
    const ctx = (event && event.context) || {};
    const info = {
      ts: new Date().toISOString(),
      topKeys: Object.keys(event || {}),
      ctxKeys: Object.keys(ctx),
      sessionKey: event.sessionKey ?? ctx.sessionKey,
      contentPreview: String(event.content ?? ctx.textContent ?? ctx.content ?? '').slice(0, 120),
    };
    ensureDir(PROBE_LOG);
    fs.appendFileSync(PROBE_LOG, JSON.stringify(info) + '\n');
  } catch (e) { /* silent */ }
}

function logAction(entry) {
  try {
    ensureDir(ACTION_LOG);
    fs.appendFileSync(ACTION_LOG, JSON.stringify({ ts: new Date().toISOString(), ...entry }) + '\n');
  } catch (e) { /* silent */ }
}

function readCounters() {
  try {
    if (!fs.existsSync(COUNTER_PATH)) return {};
    return JSON.parse(fs.readFileSync(COUNTER_PATH, 'utf-8'));
  } catch (e) {
    return {};
  }
}

function writeCounters(data) {
  try {
    ensureDir(COUNTER_PATH);
    fs.writeFileSync(COUNTER_PATH, JSON.stringify(data, null, 2));
  } catch (e) { /* silent */ }
}

function extractSessionKey(event) {
  const ctx = (event && event.context) || {};
  return String(event.sessionKey ?? ctx.sessionKey ?? '');
}

function extractContent(event) {
  const ctx = (event && event.context) || {};
  return String(event.content ?? ctx.textContent ?? ctx.content ?? '').trim();
}

function isOverloadMessage(text) {
  if (!text) return false;
  return OVERLOAD_PATTERNS.some((re) => re.test(text));
}

function sendTelegramDirect(text) {
  try {
    const cfg = JSON.parse(fs.readFileSync(OPENCLAW_CONFIG_PATH, 'utf-8'));
    const botToken = cfg?.channels?.telegram?.accounts?.bot_main?.botToken;
    if (!botToken) return;
    const https = require('https');
    const labeledText = '🤖【賈維斯自動通知】\n' + text;
    const payload = JSON.stringify({ chat_id: COACH_TELEGRAM_CHAT_ID, text: labeledText });
    const req = https.request({
      hostname: 'api.telegram.org',
      path: `/bot${botToken}/sendMessage`,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
      timeout: 8000,
    }, (res) => { res.on('data', () => {}); });
    req.on('error', () => {});
    req.on('timeout', () => req.destroy());
    req.write(payload);
    req.end();
  } catch (e) { /* silent */ }
}

// 直接補一句「請繼續」進同一個 session，讓 agent 接著把任務做完。
// detached + unref + stdio:ignore：背景執行，不阻塞這次 message:sent 的處理，
// 也不等它跑完（它會自己觸發下一輪 message:sent，形成新的一次獨立事件，非遞迴呼叫）。
function triggerContinue(sessionKey) {
  try {
    const child = spawn('openclaw', [
      'agent',
      '--session-key', sessionKey,
      '--message', '請繼續',
      '--deliver',
    ], { detached: true, stdio: 'ignore' });
    child.unref();
    return true;
  } catch (e) {
    return false;
  }
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'sent') return;

  probeDump(event);

  const sessionKey = extractSessionKey(event);
  const content = extractContent(event);
  if (!sessionKey) return;

  const counters = readCounters();
  const state = counters[sessionKey] || { count: 0, escalated: false };

  if (!isOverloadMessage(content)) {
    // 收到一次正常回覆，過去的過載記錄不再有意義，重置
    if (state.count > 0 || state.escalated) {
      delete counters[sessionKey];
      writeCounters(counters);
      logAction({ sessionKey, outcome: 'reset_on_normal_reply' });
    }
    return;
  }

  if (state.escalated) {
    // 已經升級請教練裁示過，避免持續過載時無限重複打擾，靜默記錄即可
    logAction({ sessionKey, outcome: 'skip_already_escalated' });
    return;
  }

  const nextCount = (state.count || 0) + 1;

  if (nextCount <= MAX_AUTO_RETRY) {
    const spawned = triggerContinue(sessionKey);
    counters[sessionKey] = { count: nextCount, escalated: false, lastTs: new Date().toISOString() };
    writeCounters(counters);
    logAction({ sessionKey, outcome: spawned ? 'auto_continue_triggered' : 'auto_continue_spawn_failed', count: nextCount });
    if (spawned) {
      sendTelegramDirect(`偵測到MiniMax過載，已自動幫您接續對話（第${nextCount}次），不用您動手。`);
    }
  } else {
    counters[sessionKey] = { count: nextCount, escalated: true, lastTs: new Date().toISOString() };
    writeCounters(counters);
    logAction({ sessionKey, outcome: 'escalated_to_coach', count: nextCount });
    sendTelegramDirect(`⚠️ MiniMax已連續過載超過${MAX_AUTO_RETRY}次自動接續仍未恢復，我先停手不再自動重試，請您決定：要繼續等，還是先換模型？`);
  }
};

module.exports = handler;
module.exports.default = handler;

