"use strict";
// 測試 hooks/minimax-overload-autocontinue/handler.js
// 攔截真實 Telegram 發送 + 真實 spawn('openclaw', ...)，避免測試真的打通知或真的觸發 agent 續跑。
// 跑完還原真實 counter 檔案，不影響正式狀態。

const fs = require('fs');
const path = require('path');
const https = require('https');
const cp = require('child_process');

let telegramSentCount = 0;
https.request = function (opts, cb) {
  telegramSentCount++;
  const fakeRes = { on: () => {} };
  if (cb) setTimeout(() => cb(fakeRes), 0);
  return { on: () => {}, write: () => {}, end: () => {}, destroy: () => {} };
};

const spawnCalls = [];
cp.spawn = function (cmd, args, opts) {
  spawnCalls.push({ cmd, args, opts });
  return { unref: () => {} };
};

const HANDLER_PATH = path.join(process.env.HOME, '.openclaw', 'hooks', 'minimax-overload-autocontinue', 'handler.js');
const COUNTER_PATH = path.join(process.env.HOME, '.openclaw', 'workspace', 'state', 'minimax_overload_retry.json');

function mkEvent({ sessionKey = 'agent:main:telegram:direct:6124913915', text = '正常回覆' } = {}) {
  return { type: 'message', action: 'sent', sessionKey, context: { textContent: text } };
}

function resetCounter() {
  try { fs.unlinkSync(COUNTER_PATH); } catch (e) {}
}

function readCounters() {
  try { return JSON.parse(fs.readFileSync(COUNTER_PATH, 'utf-8')); } catch (e) { return {}; }
}

async function run() {
  let backup = null;
  try { backup = fs.readFileSync(COUNTER_PATH, 'utf-8'); } catch (e) {}

  delete require.cache[require.resolve(HANDLER_PATH)];
  const handler = require(HANDLER_PATH);
  let pass = 0, fail = 0;

  function check(name, cond) {
    console.log((cond ? '✅' : '❌'), name);
    cond ? pass++ : fail++;
  }

  const OVERLOAD_TEXT = 'The AI service is temporarily overloaded. Please try again in a moment.';

  console.log('=== 正常訊息不觸發，不寫入counter ===');
  resetCounter();
  spawnCalls.length = 0; telegramSentCount = 0;
  await handler(mkEvent({ text: '任務已完成，這是結果。' }));
