  console.log('=== 非message:sent事件應忽略 ===');
  spawnCalls.length = 0;
  await handler({ type: 'message', action: 'preprocessed', context: {} });
  await handler(null);
  check('非sent事件+null事件都不炸掉、不觸發', spawnCalls.length === 0);

